import{_ as i,o as e,c as a,e as r}from"./app-6c9584fa.js";const u={};function t(h,l){return e(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="前端架构设计" tabindex="-1"><a class="header-anchor" href="#前端架构设计" aria-hidden="true">#</a> 前端架构设计</h1><h2 id="_1-业务与体验目标" tabindex="-1"><a class="header-anchor" href="#_1-业务与体验目标" aria-hidden="true">#</a> 1. 业务与体验目标</h2><ol><li>业务边界： <ul><li>产品要解决什么问题？核心用户旅程有哪些（登录、浏览、下单、支付、内容发布等）？</li><li>哪些页面/模块是核心链路，哪些是可延后或可降级的非核心链路？</li></ul></li><li>体验指标： <ul><li>首屏与交互体验：TTFB、FCP、LCP、INP、CLS 的目标值和衡量方式。</li><li>弱网/低端机：加载策略、骨架屏、降级策略、离线可用性。</li></ul></li><li>可演进性与团队协作： <ul><li>项目生命周期（短期活动页 vs 长期产品）。</li><li>团队规模与协作模式（多人并行、跨团队共建、组件复用诉求）。</li></ul></li></ol><h2 id="_2-技术栈与运行环境" tabindex="-1"><a class="header-anchor" href="#_2-技术栈与运行环境" aria-hidden="true">#</a> 2. 技术栈与运行环境</h2><ol><li>运行环境与兼容： <ul><li>浏览器与版本范围、是否要支持 WebView、小程序、Electron、桌面端等。</li><li>国际化/多时区/多语言输入，字体与排版差异。</li></ul></li><li>渲染形态选择： <ul><li>CSR：交互强、迭代快，但首屏与 SEO 可能弱。</li><li>SSR：首屏更好，适合内容型/SEO，但成本更高。</li><li>SSG/ISR：适合内容与营销页，配合增量更新。</li><li>混合渲染：按路由/页面选择最佳渲染策略。</li></ul></li><li>框架与工具链： <ul><li>React/Vue/Svelte 等选择依据（生态、团队熟悉度、性能诉求）。</li><li>包管理与构建（pnpm/yarn、Vite/Webpack、Babel/SWC）。</li></ul></li></ol><h2 id="_3-模块划分与项目结构" tabindex="-1"><a class="header-anchor" href="#_3-模块划分与项目结构" aria-hidden="true">#</a> 3. 模块划分与项目结构</h2><ol><li>按领域划分模块： <ul><li>以业务域而非页面堆叠组织代码（如 user、order、payment、content）。</li><li>领域模块内部再分：ui、model、service、hooks/utils。</li></ul></li><li>分层结构建议： <ul><li>presentation：页面与视图组件（负责渲染与交互）。</li><li>domain：领域模型、状态与业务规则。</li><li>application：编排用例（跨领域流程、接口编排）。</li><li>infrastructure：HTTP/Storage/Telemetry 等基础设施封装。</li></ul></li><li>依赖方向与边界： <ul><li>让上层依赖下层，禁止反向依赖，避免组件互相引用形成“网状结构”。</li><li>对外部依赖（SDK/第三方库）做适配层，避免业务代码直接散落调用。</li></ul></li></ol><h2 id="_4-路由与导航体系" tabindex="-1"><a class="header-anchor" href="#_4-路由与导航体系" aria-hidden="true">#</a> 4. 路由与导航体系</h2><ol><li>路由设计： <ul><li>路由分组、动态路由、权限路由、嵌套路由、布局路由。</li><li>URL 作为状态：可分享、可回放、可 SEO 的关键参数应在 URL 中。</li></ul></li><li>访问控制： <ul><li>未登录跳转、登录态刷新、token 过期处理、第三方登录回调。</li><li>路由级别的权限守卫与资源级别的鉴权分离。</li></ul></li><li>预加载与分包： <ul><li>路由级 code splitting、按业务域拆包、按场景预加载。</li><li>首屏最小化依赖、次屏按需加载。</li></ul></li></ol><h2 id="_5-状态管理与数据流" tabindex="-1"><a class="header-anchor" href="#_5-状态管理与数据流" aria-hidden="true">#</a> 5. 状态管理与数据流</h2><ol><li>状态分类： <ul><li>Server State：来自后端的数据（列表、详情、权限、配置）。</li><li>Client UI State：弹窗、选中态、编辑态、表单草稿等。</li><li>Cross-Page State：跨页面共享的用户信息、购物车等。</li></ul></li><li>管理方案： <ul><li>Server State：优先用请求库的缓存能力（如 Query 类库），减少手写缓存。</li><li>Client State：局部优先（组件 state），必要时再上全局状态。</li><li>表单状态：表单库与 schema 校验（规则复用、错误提示统一）。</li></ul></li><li>数据一致性与刷新策略： <ul><li>缓存键设计、失效策略、乐观更新与回滚。</li><li>幂等与重复提交防护（按钮节流、请求幂等键）。</li></ul></li></ol><h2 id="_6-api-与通信层设计" tabindex="-1"><a class="header-anchor" href="#_6-api-与通信层设计" aria-hidden="true">#</a> 6. API 与通信层设计</h2><ol><li>API 契约： <ul><li>统一的响应结构、错误码规范、分页/排序/过滤统一参数。</li><li>OpenAPI/契约校验，减少前后端对齐成本。</li></ul></li><li>通信封装： <ul><li>统一的 request client（拦截器、超时、重试、取消、错误归一化）。</li><li>token 刷新策略：并发刷新锁、失败重登、无感续期策略。</li></ul></li><li>实时与流式： <ul><li>WebSocket/SSE：用于消息、协作、流式输出。</li><li>断线重连、心跳、消息顺序与幂等处理。</li></ul></li></ol><h2 id="_7-性能与加载策略" tabindex="-1"><a class="header-anchor" href="#_7-性能与加载策略" aria-hidden="true">#</a> 7. 性能与加载策略</h2><ol><li>性能预算： <ul><li>按页面给出 JS/CSS/图片体积预算，设定 LCP/INP 目标。</li></ul></li><li>资源策略： <ul><li>图片：响应式图片、懒加载、WebP/AVIF、CDN。</li><li>字体：子集化、font-display、预加载策略。</li><li>第三方脚本：延迟加载、沙箱隔离、失败降级。</li></ul></li><li>代码与渲染优化： <ul><li>减少不必要渲染：memo、拆分组件、虚拟列表。</li><li>重计算控制：节流/防抖、Web Worker、分帧处理。</li><li>长任务治理：监控与拆分，避免卡顿。</li></ul></li></ol><h2 id="_8-设计系统与组件体系" tabindex="-1"><a class="header-anchor" href="#_8-设计系统与组件体系" aria-hidden="true">#</a> 8. 设计系统与组件体系</h2><ol><li>组件分层： <ul><li>基础组件：Button/Input/Modal（无业务语义）。</li><li>业务组件：OrderCard/UserAvatar（有业务语义，可复用）。</li><li>页面组件：只服务于单页，不强求复用。</li></ul></li><li>设计系统： <ul><li>主题、token（颜色、间距、字体、阴影）、暗色模式。</li><li>可访问性：键盘操作、ARIA、对比度、焦点管理。</li></ul></li><li>组件文档与测试： <ul><li>Storybook/文档站，明确 API 与用法。</li><li>组件回归测试与视觉回归测试。</li></ul></li></ol><h2 id="_9-工程化与质量保障" tabindex="-1"><a class="header-anchor" href="#_9-工程化与质量保障" aria-hidden="true">#</a> 9. 工程化与质量保障</h2><ol><li>代码规范： <ul><li>lint、格式化、提交规范、变更日志策略。</li><li>单元边界与导入规则，避免跨层引用。</li></ul></li><li>测试策略： <ul><li>单元测试：工具函数、业务规则、关键 hooks。</li><li>集成测试：关键用户旅程（登录-下单-支付）。</li><li>E2E：核心路径自动化回归。</li></ul></li><li>CI/CD： <ul><li>构建、测试、产物发布、灰度、回滚。</li><li>预览环境：PR 级别预览，减少联调成本。</li></ul></li></ol><h2 id="_10-安全与风控" tabindex="-1"><a class="header-anchor" href="#_10-安全与风控" aria-hidden="true">#</a> 10. 安全与风控</h2><ol><li>前端安全基础： <ul><li>XSS/CSRF/CSP、输入输出处理、Cookie 策略（SameSite/HttpOnly）。</li><li>依赖安全：漏洞扫描、锁版本策略、供应链风险。</li></ul></li><li>鉴权与权限展示： <ul><li>前端权限只能用于展示与交互控制，真正权限必须由后端校验。</li><li>防止越权：接口层统一处理 401/403，UI 层一致反馈。</li></ul></li><li>风控与反作弊： <ul><li>行为埋点、验证码、人机校验、频控策略、设备指纹（合规前提下）。</li></ul></li></ol><h2 id="_11-可观测性-监控、日志与埋点" tabindex="-1"><a class="header-anchor" href="#_11-可观测性-监控、日志与埋点" aria-hidden="true">#</a> 11. 可观测性：监控、日志与埋点</h2><ol><li>性能监控： <ul><li>Web Vitals 上报、首屏耗时、资源加载失败率、JS 错误率。</li></ul></li><li>日志与追踪： <ul><li>统一 requestId/traceId，前端把 traceId 透传给后端，便于排障。</li><li>关键链路埋点：登录成功率、支付成功率、下单转化等。</li></ul></li><li>报警与回放： <ul><li>错误聚合、版本维度对比、用户会话回放用于复现问题。</li></ul></li></ol><h2 id="_12-发布、灰度与多环境" tabindex="-1"><a class="header-anchor" href="#_12-发布、灰度与多环境" aria-hidden="true">#</a> 12. 发布、灰度与多环境</h2><ol><li>环境管理： <ul><li>dev/test/stage/prod 环境隔离，配置按环境下发。</li><li>feature flag：新功能开关、灰度人群、快速回滚。</li></ul></li><li>发布策略： <ul><li>静态资源版本化与缓存策略（hash、Cache-Control、CDN 回源）。</li><li>灰度发布：按用户、地域、Header、百分比进行流量切分。</li></ul></li><li>兼容与回滚： <ul><li>前后端版本兼容窗口，接口版本管理，避免“先发前端后端未就绪”。</li></ul></li></ol><h2 id="_13-多端与微前端-可选" tabindex="-1"><a class="header-anchor" href="#_13-多端与微前端-可选" aria-hidden="true">#</a> 13. 多端与微前端（可选）</h2><ol><li>多端统一策略： <ul><li>组件与业务逻辑复用（monorepo、多包架构、共享 SDK）。</li><li>适配层：Web/小程序/APP 的差异抽象。</li></ul></li><li>微前端适用场景： <ul><li>多团队、多业务线、独立发布诉求强。</li><li>需要明确：运行时隔离、路由冲突、样式隔离、性能成本。</li></ul></li><li>与设计系统的配合： <ul><li>统一 UI token、统一基础组件，减少割裂感。</li></ul></li></ol><hr><p>上面的内容可以直接当作「前端架构设计检查清单」：从业务目标与渲染策略 → 模块划分与数据流 → 性能与组件体系 → 工程化、可观测性与发布治理，逐项补齐后，就是一份可落地的前端架构方案。</p>',29)])])}const o=i(u,[["render",t],["__file","前端架构设计.html.vue"]]);export{o as default};
